class Solution:
    def getWordsInLongestSubsequence(self, words: List[str], groups: List[int]) -> List[str]:
        n = len(words)
        dp = [[word] for word in words]
        max_len = 1

        for i in range(1, n):
            if groups[i] != groups[i - 1]:
                for j in range(i):
                    if len(words[j]) == len(words[i]) and self.hamming_distance(words[j], words[i]) == 1:
                        if len(dp[j]) + 1 > len(dp[i]):
                            dp[i] = dp[j] + [words[i]]
                            max_len = max(max_len, len(dp[i]))

        for i in range(n):
            if len(dp[i]) == max_len:
                return dp[i]

    def hamming_distance(self, s1: str, s2: str) -> int:
        return sum(c1 != c2 for c1, c2 in zip(s1, s2))

