class Solution:
    def minPushBox(self, grid: List[List[str]]) -> int:
        m, n = len(grid), len(grid[0])
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 'S':
                    start = (i, j)
                elif grid[i][j] == 'B':
                    box = (i, j)
                elif grid[i][j] == 'T':
                    target = (i, j)

        def is_valid(x, y):
            return 0 <= x < m and 0 <= y < n and grid[x][y] != '#'

        def can_reach(start, end, blocked):
            queue = deque([start])
            visited = set([start])
            while queue:
                x, y = queue.popleft()
                if (x, y) == end:
                    return True
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy
                    if is_valid(nx, ny) and (nx, ny) not in visited and (nx, ny) != blocked:
                        queue.append((nx, ny))
                        visited.add((nx, ny))
            return False

        step = 0
        queue = deque([(box, start)])
        visited = set([(box, start)])
        while queue:
            size = len(queue)
            for _ in range(size):
                box, player = queue.popleft()
                if box == target:
                    return step
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    new_box_x, new_box_y = box[0] + dx, box[1] + dy
                    new_player_x, new_player_y = box[0] - dx, box[1] - dy
                    if is_valid(new_box_x, new_box_y) and is_valid(new_player_x, new_player_y) and (new_box_x, new_box_y) != player and ((new_box_x, new_box_y), new_player_x, new_player_y) not in visited and can_reach(player, (new_box_x, new_box_y), box):
                        queue.append(((new_box_x, new_box_y), (new_player_x, new_player_y)))
                        visited.add(((new_box_x, new_box_y), new_player_x, new_player_y))
            step += 1
        return -1

