from collections import Counter

class Solution:
    def recoverArray(self, nums: List[int]) -> List[int]:
        nums.sort()
        n = len(nums)
        count = Counter(nums)

        for i in range(1, n):
            k = (nums[i] - nums[0]) // 2
            if k > 0 and nums[i] - nums[0] == 2 * k:
                original = []
                temp_count = count.copy()
                for num in nums:
                    if temp_count[num] == 0:
                        continue
                    if temp_count[num + 2 * k] == 0:
                        break
                    original.append(num + k)
                    temp_count[num] -= 1
                    temp_count[num + 2 * k] -= 1
                else:
                    return original
        return []

