class Solution:
    def searchBST(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:
        current = root
        while current:
            if current.val == val:
                return current
            elif current.val < val:
                current = current.right
            else:
                current = current.left
        return None

class Solution:
    def checkAlmostEquivalent(self, word1: str, word2: str) -> bool:
        count = [0] * 26

        for c in word1:
            count[ord(c) - ord('a')] += 1

        for c in word2:
            count[ord(c) - ord('a')] -= 1

        for diff in count:
            if abs(diff) > 3:
                return False

        return True

