class Solution:
    def maximumSafenessFactor(self, grid: List[List[int]]) -> int:
        n = len(grid)
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        # BFS to compute the safeness factor for each cell
        queue = deque()
        visited = [[False] * n for _ in range(n)]
        safeness = [[0] * n for _ in range(n)]

        # Initialize the queue with all thief positions
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    queue.append((i, j))
                    visited[i][j] = True

        # Perform BFS to fill the safeness factor
        level = 0
        while queue:
            level_size = len(queue)
            for _ in range(level_size):
                x, y = queue.popleft()
                safeness[x][y] = level
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                        visited[nx][ny] = True
                        queue.append((nx, ny))
            level += 1

        # Binary search to find the maximum safeness factor
        def can_reach_with_safeness(min_safeness):
            visited = [[False] * n for _ in range(n)]
            queue = deque([(0, 0)])
            visited[0][0] = True

            while queue:
                x, y = queue.popleft()
                if x == n - 1 and y == n - 1:
                    return True
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny] and safeness[nx][ny] >= min_safeness:
                        visited[nx][ny] = True
                        queue.append((nx, ny))
            return False

        left, right = 0, n * n
        result = 0
        while left <= right:
            mid = (left + right) // 2
            if can_reach_with_safeness(mid):
                result = mid
                left = mid + 1
            else:
                right = mid - 1

        return result

