class Solution:
    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        def backtrack(start, target, path):
            if target == 0:
                result.append(path)
                return
            if target < 0:
                return
            for i in range(start, len(candidates)):
                backtrack(i, target - candidates[i], path + [candidates[i]])

        result = []
        backtrack(0, target, [])
        return result

class Solution:
    def openLock(self, deadends: List[str], target: str) -> int:
        deadends = set(deadends)
        if '0000' in deadends:
            return -1

        queue = deque([('0000', 0)])
        visited = set(['0000'])

        while queue:
            current, steps = queue.popleft()

            if current == target:
                return steps

            for i in range(4):
                for d in (-1, 1):
                    new_digit = (int(current[i]) + d) % 10
                    new_combination = current[:i] + str(new_digit) + current[i+1:]

                    if new_combination not in deadends and new_combination not in visited:
                        visited.add(new_combination)
                        queue.append((new_combination, steps + 1))

        return -1

