class Solution:
    def cycleLengthQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        def find_depth(val):
            depth = 0
            while val > 1:
                val //= 2
                depth += 1
            return depth

        def find_lca(a, b):
            depth_a = find_depth(a)
            depth_b = find_depth(b)

            if depth_a < depth_b:
                a, b = b, a
                depth_a, depth_b = depth_b, depth_a

            # Move a to the same depth as b
            for _ in range(depth_a - depth_b):
                a //= 2

            # Move both a and b up until they meet
            while a != b:
                a //= 2
                b //= 2

            return a

        result = []
        for a, b in queries:
            lca = find_lca(a, b)
            # Cycle length is the sum of depths from a and b to LCA plus one for the edge between a and b
            cycle_length = find_depth(a) - find_depth(lca) + find_depth(b) - find_depth(lca) + 1
            result.append(cycle_length)

        return result

class Solution:
    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        def backtrack(start, path, current_sum):
            if current_sum == target:
                result.append(path)
                return
            if current_sum > target:
                return

            for i in range(start, len(candidates)):
                backtrack(i, path + [candidates[i]], current_sum + candidates[i])

        result = []
        backtrack(0, [], 0)
        return result

class Solution:
    def floodFill(self, image: List[List[int]], sr: int, sc: int, color: int) -> List[List[int]]:
        if not image or not image[0]:
            return []

        directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
        original_color = image[sr][sc]

        def dfs(i, j):
            if i < 0 or i >= len(image) or j < 0 or j >= len(image[0]) or image[i][j] != original_color:
                return

            image[i][j] = color
            for dx, dy in directions:
                dfs(i + dx, j + dy)

        dfs(sr, sc)
        return image

