class Solution:
    def boxDelivering(self, boxes: List[List[int]], portsCount: int, maxBoxes: int, maxWeight: int) -> int:
        n = len(boxes)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        extra_trips = 0
        weight = 0
        j = 0

        for i in range(n):
            while j < n and j - i + 1 <= maxBoxes and weight + boxes[j][1] <= maxWeight:
                weight += boxes[j][1]
                if j == 0 or boxes[j][0] != boxes[j - 1][0]:
                    extra_trips += 1
                j += 1

            dp[j] = min(dp[j], dp[i] + extra_trips + 1)

            if boxes[i][0] != boxes[i + 1][0] if i + 1 < n else True:
                extra_trips -= 1
            weight -= boxes[i][1]

        return dp[n]

