class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        nums.sort()
        max_xor = 0
        left = 0

        for right in range(len(nums)):
            while nums[right] - nums[left] > nums[left]:
                left += 1
            for i in range(left, right):
                max_xor = max(max_xor, nums[i] ^ nums[right])

        return max_xor

class Solution:
    def decodeMessage(self, key: str, message: str) -> str:
        # Create a mapping from the key to the alphabet
        key = key.replace(" ", "")  # Remove spaces from the key
        unique_key = []
        for char in key:
            if char not in unique_key:
                unique_key.append(char)

        # Create a dictionary for the substitution table
        substitution_table = {}
        alphabet = "abcdefghijklmnopqrstuvwxyz"
        for i in range(26):
            substitution_table[unique_key[i]] = alphabet[i]

        # Decode the message
        decoded_message = []
        for char in message:
            if char == " ":
                decoded_message.append(" ")
            else:
                decoded_message.append(substitution_table[char])

        return "".join(decoded_message)

class Solution:
    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        res = []
        def backtrack(candidates, path, start):
            if sum(path) == target:
                res.append(path[:])
                return
            if sum(path) > target:
                return

            for i in range(start, len(candidates)):
                path.append(candidates[i])
                backtrack(candidates, path, i)
                path.pop()

        backtrack(candidates, [], 0)
        return res

class Solution:
    def minimumAverage(self, nums: List[int]) -> float:
        averages = []
        nums.sort()

        while nums:
            minElement = nums.pop(0)
            maxElement = nums.pop(-1)
            average = (minElement + maxElement) / 2
            averages.append(average)

        return min(averages)

class Solution:
    def findDisappearedNumbers(self, nums: List[int]) -> List[int]:
