class Solution:
    def minTrioDegree(self, n: int, edges: List[List[int]]) -> int:
        # Build the adjacency list
        adj_list = [[] for _ in range(n + 1)]
        for u, v in edges:
            adj_list[u].append(v)
            adj_list[v].append(u)

        # Initialize the degree array
        degree = [0] * (n + 1)
        for i in range(1, n + 1):
            degree[i] = len(adj_list[i])

        # Find all trios
        min_degree = float('inf')
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                for k in range(j + 1, n + 1):
                    if k in adj_list[i] and k in adj_list[j] and i in adj_list[k]:
                        # Calculate the degree of the trio
                        trio_degree = degree[i] + degree[j] + degree[k] - 6
                        min_degree = min(min_degree, trio_degree)

        return min_degree if min_degree != float('inf') else -1

class Solution:
    def halvesAreAlike(self, s: str) -> bool:
