class Solution:
    def findLUSlength(self, strs: List[str]) -> int:
        # Create a dictionary to count occurrences of each string
        str_counts = {}
        for s in strs:
            if s in str_counts:
                str_counts[s] += 1
            else:
                str_counts[s] = 1

        # Initialize variables to keep track of the longest uncommon subsequence length and its corresponding string
        max_length = -1
        longest_string = ""

        # Iterate through each string in the list
        for s in strs:
            # Check if the string appears only once in the list
            if str_counts[s] == 1:
                # Update the maximum length and the longest string if this string is longer than the current longest one
                if len(s) > max_length:
                    max_length = len(s)
                    longest_string = s

        return max_length

