class Solution:
    def numOfBurgers(self, tomatoSlices: int, cheeseSlices: int) -> List[int]:
        if tomatoSlices % 2 != 0 or tomatoSlices < cheeseSlices * 2 or cheeseSlices > tomatoSlices // 2:
            return []

        total_jumbo = (tomatoSlices - 2 * cheeseSlices) // 2
        total_small = cheeseSlices - total_jumbo

        return [total_jumbo, total_small]

class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        ones, twos = 0, 0
        for num in nums:
            ones = (ones ^ num) & ~twos
            twos = (twos ^ num) & ~ones
        return ones

from collections import deque

class Solution:
    def openLock(self, deadends: List[str], target: str) -> int:
        if "0000" in deadends:
            return -1

        visited = set(deadends)
        queue = deque([('0000', 0)])

        while queue:
            current, steps = queue.popleft()

            if current == target:
                return steps

            for i in range(4):
                digit = int(current[i])

                # Turn clockwise
                next_digit = (digit + 1) % 10
                next_state = current[:i] + str(next_digit) + current[i+1:]
                if next_state not in visited:
                    visited.add(next_state)
                    queue.append((next_state, steps + 1))

                # Turn counterclockwise
                next_digit = (digit - 1) % 10
                next_state = current[:i] + str(next_digit) + current[i+1:]
                if next_state not in visited:
                    visited.add(next_state)
                    queue.append((next_state, steps + 1))

        return -1

class Solution:
    def maxProductPath(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dp_max = [[0] * n for _ in range(m)]
        dp_min = [[0] * n for _ in range(m)]

        # Initialize the first cell
        dp_max[0][0] = dp_min[0][0] = grid[0][0]

        # Fill the first row
        for j in range(1, n):
            dp_max[0][j] = dp_max[0][j-1] * grid[0][j]
            dp_min[0][j] = dp_min[0][j-1] * grid[0][j]

        # Fill the first column
        for i in range(1, m):
            dp_max[i][0] = dp_max[i-1][0] * grid[i][0]
            dp_min[i][0] = dp_min[i-1][0] * grid[i][0]

        # Fill the rest of the table
        for i in range(1, m):
            for j in range(1, n):
                if grid[i][j] < 0:
                    dp_max[i][j] = max(dp_min[i-1][j] * grid[i][j], dp_min[i][j-1] * grid[i][j])
                    dp_min[i][j] = min(dp_max[i-1][j] * grid[i][j], dp_min[i][j-1] * grid[i][j])
                else:
                    dp_max[i][j] = max(dp_max[i-1][j] * grid[i][j], dp_max[i][j-1] * grid[i][j])
                    dp_min[i][j] = min(dp_min[i-1][j] * grid[i][j], dp_min[i][j-1] * grid[i][j])

        # Return the result modulo 10^9 + 7
        return dp_max[m-1][n-1] % (10**9 + 7) if dp_max[m-1][n-1] >= 0 else -1

