class Solution:
    def canThreePartsEqualSum(self, arr: List[int]) -> bool:
        total_sum = sum(arr)
        if total_sum % 3 != 0:
            return False

        target_sum = total_sum // 3
        current_sum = 0
        part_count = 0

        for num in arr:
            current_sum += num
            if current_sum == target_sum:
                part_count += 1
                current_sum = 0

        return part_count == 3

