class Solution:
    def splitArray(self, nums: List[int]) -> bool:
        left_sums = [0]
        right_sums = [0]
        for num in nums:
            left_sums.append(left_sums[-1] + num)
            right_sums.insert(0, right_sums[0] + num)
        for i in range(len(nums)-3):
            if left_sums[i+1] == right_sums[i+2]:
                return True
        return False

