class Solution:
    def calculateTax(self, brackets: List[List[int]], income: int) -> float:
        tax = 0.0
        prev_upper = 0

        for upper, percent in brackets:
            if income >= upper:
                tax += (upper - prev_upper) * percent / 100
                prev_upper = upper
            else:
                tax += (income - prev_upper) * percent / 100
                break

        return tax

from collections import Counter

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        counter = Counter(nums)
        res = 0

        for count in counter.values():
            if count % 3 == 0:
                res += count // 3
            elif count % 3 == 1:
                res += (count - 4) // 3 + 2
            elif count % 3 == 2:
                res += (count - 2) // 3 + 1

            if count < 3:
                return -1

        return res

class Solution:
    def findRelativeRanks(self, score: List[int]) -> List[str]:
        # Create a dictionary to map each score to its index
        score_to_index = {score[i]: i for i in range(len(score))}

        # Sort the scores in descending order
        sorted_scores = sorted(score, reverse=True)

        # Initialize the result list with empty strings
        result = [''] * len(score)

        # Assign ranks based on the sorted scores
        for i, score in enumerate(sorted_scores):
            if i == 0:
                result[score_to_index[score]] = 'Gold Medal'
            elif i == 1:
                result[score_to_index[score]] = 'Silver Medal'
            elif i == 2:
                result[score_to_index[score]] = 'Bronze Medal'
            else:
                result[score_to_index[score]] = str(i + 1)

        return result

