class Solution:
    def gcdSort(self, nums: List[int]) -> bool:
        def find(x):
            if x != parent[x]:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY

        maxNum = max(nums)
        parent = list(range(maxNum + 1))

        # Sieve of Eratosthenes to find prime factors
        sieve = [True] * (maxNum + 1)
        for i in range(2, maxNum + 1):
            if sieve[i]:
                for j in range(i, maxNum + 1, i):
                    union(i, j)
                    sieve[j] = False

        sortedNums = sorted(nums)
        for i in range(len(nums)):
            if find(nums[i]) != find(sortedNums[i]):
                return False
        return True

class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        N = len(graph)
        visited = set()
        groups = {}
        group_id = 0

        def dfs(node):
            if node in visited:
                return
            visited.add(node)
            groups[group_id].add(node)
            for i in range(N):
                if graph[node][i] == 1 and i not in visited:
                    dfs(i)

        for i in initial:
            if i not in visited:
                groups[group_id] = set()
                dfs(i)
                group_id += 1

        max_count = 0
        best_node = float('inf')
        for node in initial:
            count = sum(1 for group in groups.values() if node in group)
            if count > max_count:
                max_count = count
                best_node = node
            elif count == max_count:
                best_node = min(best_node, node)

        return best_node

