import functools

class Solution:
    def shoppingOffers(self, price: List[int], special: List[List[int]], needs: List[int]) -> int:
        @functools.lru_cache(None)
        def dfs(needs):
            # Calculate the cost without any special offers
            res = sum(n * p for n, p in zip(needs, price))
            # Try each special offer
            for s in special:
                next_needs = tuple(n - o for n, o in zip(needs, s[:-1]))
                if all(x >= 0 for x in next_needs):
                    res = min(res, dfs(next_needs) + s[-1])
            return res

        return dfs(tuple(needs))

class Solution:
    def findThePrefixCommonArray(self, A: List[int], B: List[int]) -> List[int]:
        result = []
        for i in range(len(A)):
            set_A = set(A[:i+1])
            set_B = set(B[:i+1])
            result.append(len(set_A.intersection(set_B)))
        return result

class Solution:
    def matrixScore(self, grid: List[List[int]]) -> int:
        # Ensure every row starts with 1
        for i in range(len(grid)):
            if grid[i][0] == 0:
                for j in range(len(grid[0])):
                    grid[i][j] = 1 - grid[i][j]

        # Ensure every column has more 1s than 0s
        for j in range(1, len(grid[0])):
            count_ones = sum(grid[i][j] for i in range(len(grid)))
            if count_ones < len(grid) // 2:
                for i in range(len(grid)):
                    grid[i][j] = 1 - grid[i][j]

        # Calculate the score
        score = 0
        for row in grid:
            score += int(''.join(map(str, row)), 2)

        return score

