        for start, end in zip(l, r):
            subarray = sorted(nums[start:end+1])
            diff = subarray[1] - subarray[0]
            is_arithmetic = all(subarray[i] - subarray[i-1] == diff for i in range(2, len(subarray)))
            result.append(is_arithmetic)
