class Solution:
    def minTrioDegree(self, n: int, edges: List[List[int]]) -> int:
        # Create an adjacency list to represent the graph
        adj_list = {i: set() for i in range(1, n + 1)}
        for u, v in edges:
            adj_list[u].add(v)
            adj_list[v].add(u)

        min_degree = float('inf')
        found_trio = False

        # Check all combinations of three nodes
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                if j not in adj_list[i]:
                    continue
                for k in range(j + 1, n + 1):
                    if k not in adj_list[i] or k not in adj_list[j]:
                        continue
                    # Found a trio (i, j, k)
                    found_trio = True
                    # Calculate the degree of the trio
                    degree = (len(adj_list[i]) + len(adj_list[j]) + len(adj_list[k])) - 6
                    min_degree = min(min_degree, degree)

        return min_degree if found_trio else -1

class Solution:
    def twoSum(self, numbers: List[int], target: int) -> List[int]:
        left, right = 0, len(numbers) - 1

        while left < right:
            current_sum = numbers[left] + numbers[right]

            if current_sum == target:
                return [left + 1, right + 1]
            elif current_sum < target:
                left += 1
            else:
                right -= 1

        return []

