class Solution:
    def getMaximumXor(self, nums: List[int], maximumBit: int) -> List[int]:
        result = []
        xor_sum = 0
        for num in nums:
            xor_sum ^= num
        max_value = (1 << maximumBit) - 1
        for num in reversed(nums):
            result.append(max_value ^ xor_sum)
            xor_sum ^= num
        return result

