class Solution:
    def minimumLines(self, stockPrices: List[List[int]]) -> int:
        if len(stockPrices) < 2:
            return 0

        # Sort the stock prices by day
        stockPrices.sort(key=lambda x: x[0])

        # Calculate the slope between each pair of consecutive points
        slopes = []
        for i in range(1, len(stockPrices)):
            dx = stockPrices[i][0] - stockPrices[i-1][0]
            dy = stockPrices[i][1] - stockPrices[i-1][1]
            if dx == 0:
                slopes.append(float('inf'))  # Vertical line case
            else:
                slope = dy / dx
                slopes.append(slope)

        # Count the number of unique slopes
        unique_slopes = set(slopes)
        return len(unique_slopes)

