class Solution:
    def criticalConnections(self, n: int, connections: List[List[int]]) -> List[List[int]]:
        graph = [[] for _ in range(n)]
        for u, v in connections:
            graph[u].append(v)
            graph[v].append(u)

        rank = [-1] * n
        low = [-1] * n
        time = [0]
        result = []

        def dfs(node, parent):
            rank[node] = low[node] = time[0]
            time[0] += 1

            for neighbor in graph[node]:
                if rank[neighbor] == -1:
                    dfs(neighbor, node)
                    low[node] = min(low[node], low[neighbor])

                    if low[neighbor] > rank[node]:
                        result.append([node, neighbor])
                elif neighbor != parent:
                    low[node] = min(low[node], rank[neighbor])

        for i in range(n):
            if rank[i] == -1:
                dfs(i, -1)

        return result

class Solution:
    def isSelfCrossing(self, distance: List[int]) -> bool:
        # Initialize variables to track the current position and direction
        x, y = 0, 0
        direction = 0  # 0 for North, 1 for West, 2 for South, 3 for East

        # Iterate through the distances
        for d in distance:
            # Update the position based on the current direction
            if direction == 0:
                y += d
            elif direction == 1:
                x -= d
            elif direction == 2:
                y -= d
            else:
                x += d

            # Check if the path has crossed itself
            if (x == 0 and y > 0) or (x < 0 and y >= 0):
                return True

            # Change the direction
            if direction == 0:
                direction = 1
            elif direction == 1:
                direction = 2
            elif direction == 2:
                direction = 3
            else:
                direction = 0

        return False

