class Solution:
    def maxDistToClosest(self, seats: List[int]) -> int:
        n = len(seats)
        left, right, res = -1, -1, 0

        for i in range(n):
            if seats[i] == 1:
                if left == -1:
                    left = i
                else:
                    res = max(res, (i - left) // 2)
                left = i

        if left != n - 1:
            res = max(res, n - 1 - left)

        return res

