import collections

class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        n = len(graph)
        parent = list(range(n))
        size = [1] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY
                size[rootY] += size[rootX]

        # Union all connected nodes
        for i in range(n):
            for j in range(i + 1, n):
                if graph[i][j] == 1:
                    union(i, j)

        # Count the infection source for each component
        source_count = collections.defaultdict(int)
        for node in initial:
            root = find(node)
            source_count[root] += 1

        # Find the node to remove
        result = float('inf')
        max_size = 0
        for node in sorted(initial):
            root = find(node)
            if source_count[root] == 1:
                if size[root] > max_size or (size[root] == max_size and node < result):
                    max_size = size[root]
                    result = node

        return result if result != float('inf') else min(initial)

class Solution:
    def closeStrings(self, word1: str, word2: str) -> bool:
        if len(word1) != len(word2):
            return False

        count1 = [0] * 26
        count2 = [0] * 26

        for char in word1:
            count1[ord(char) - ord('a')] += 1

        for char in word2:
            count2[ord(char) - ord('a')] += 1

        if set(count1) != set(count2):
            return False

        count1.sort()
        count2.sort()

        return count1 == count2

