class Solution:
    def minTrioDegree(self, n: int, edges: List[List[int]]) -> int:
        # Create adjacency list representation of the graph
        adj_list = defaultdict(set)
        for u, v in edges:
            adj_list[u].add(v)
            adj_list[v].add(u)

        # Initialize the minimum degree of a connected trio to infinity
        min_degree = float('inf')

        # Iterate over all possible triplets of nodes
        for i in range(1, n+1):
            for j in range(i+1, n+1):
                if j in adj_list[i]:
                    for k in range(j+1, n+1):
                        if k in adj_list[i] and k in adj_list[j]:
                            # Calculate the degree of the connected trio
                            degree = len(adj_list[i]) + len(adj_list[j]) + len(adj_list[k]) - 6
                            # Update the minimum degree if the current degree is smaller
                            min_degree = min(min_degree, degree)

        # If no connected trio was found, return -1
        return min_degree if min_degree != float('inf') else -1

from typing import List

class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        sum1, sum2 = sum(nums1), sum(nums2)

        if sum1 > sum2:
            nums1, nums2 = nums2, nums1

        target_diff = abs(sum1 - sum2)

        max_operations = []

        for num in nums1:
            max_operations.append(6 - num)

        for num in nums2:
            max_operations.append(num - 1)

        max_operations.sort(reverse=True)

        operations = 0

        for operation in max_operations:
            target_diff -= operation
            operations += 1
            if target_diff <= 0:
                return operations

        return -1

from collections import deque

class Solution:
    def shortestDistance(self, maze: List[List[int]], start: List[int], destination: List[int]) -> int:
        m, n = len(maze), len(maze[0])
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        visited = set()
        queue = deque([(start[0], start[1], 0)])
        distances = [[float('inf')] * n for _ in range(m)]
        distances[start[0]][start[1]] = 0

        while queue:
            x, y, dist = queue.popleft()
            if (x, y) == tuple(destination):
                return dist

            if (x, y) in visited:
                continue

            visited.add((x, y))

            for dx, dy in directions:
                nx, ny = x, y
                while 0 <= nx + dx < m and 0 <= ny + dy < n and maze[nx + dx][ny + dy] == 0:
                    nx += dx
                    ny += dy

                if (nx, ny) != (x, y):
                    new_dist = dist + abs(nx - x) + abs(ny - y)
                    if new_dist < distances[nx][ny]:
                        distances[nx][ny] = new_dist
                        queue.append((nx, ny, new_dist))

        return -1

