class Solution:
    def flipMatchVoyage(self, root: Optional[TreeNode], voyage: List[int]) -> List[int]:
        if not root:
            return []

        self.flipped = []
        self.index = 0

        def dfs(node):
            if not node:
                return True

            if node.val != voyage[self.index]:
                return False

            self.index += 1

            if node.left and node.left.val != voyage[self.index]:
                self.flipped.append(node.val)
                return dfs(node.right) and dfs(node.left)

            return dfs(node.left) and dfs(node.right)

        return self.flipped if dfs(root) else [-1]

class Solution:
    def meetRequirement(self, n: int, lights: List[List[int]], requirement: List[int]) -> int:
        brightness = [0] * (n + 1)

        for pos, ran in lights:
            start = max(0, pos - ran)
            end = min(n - 1, pos + ran) + 1
            brightness[start] += 1
            brightness[end] -= 1

        for i in range(1, n):
            brightness[i] += brightness[i - 1]

        count = 0
        for i in range(n):
            if brightness[i] >= requirement[i]:
                count += 1

        return count

# Definition for a binary tree node.
