class Solution:
    def getModifiedArray(self, length: int, updates: List[List[int]]) -> List[int]:
        arr = [0] * (length + 1)

        for startIdx, endIdx, inc in updates:
            arr[startIdx] += inc
            arr[endIdx + 1] -= inc

        for i in range(1, length):
            arr[i] += arr[i - 1]

        return arr[:-1]

class Solution:
    def meetRequirement(self, n: int, lights: List[List[int]], requirement: List[int]) -> int:
        diff = [0] * (n + 1)
        for pos, r in lights:
            left = max(0, pos - r)
            right = min(n, pos + r + 1)
            diff[left] += 1
            diff[right] -= 1

        current = 0
        count = 0
        for i in range(n):
            current += diff[i]
            if current >= requirement[i]:
                count += 1

        return count

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def searchBST(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:
        if not root:
            return None

        if root.val == val:
            return root
        elif root.val < val:
            return self.searchBST(root.right, val)
        else:
            return self.searchBST(root.left, val)

class Solution:
    def searchBST(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:
        if not root:
            return None
        if root.val == val:
            return root
        elif root.val > val:
            return self.searchBST(root.left, val)
        else:
            return self.searchBST(root.right, val)

class Solution:
    def getPermutation(self, n: int, k: int) -> str:
        factorial = [1]
        nums = list(range(1, n + 1))

        # Calculate factorials up to n
        for i in range(1, n):
            factorial.append(factorial[-1] * i)

        k -= 1  # Convert k to zero-based index

        result = []
        for i in range(n - 1, -1, -1):
            index = k // factorial[i]
            result.append(nums[index])
            nums.pop(index)
            k %= factorial[i]

        return ''.join(map(str, result))

class Solution:
    def search(self, nums: List[int], target: int) -> bool:
        left, right = 0, len(nums) - 1

        while left <= right:
            mid = (left + right) // 2

            if nums[mid] == target:
                return True

            # Check if the left half is sorted
            if nums[left] <= nums[mid]:
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            # Check if the right half is sorted
            else:
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1

        return False

from typing import List

class Solution:
    def findRelativeRanks(self, score: List[int]) -> List[str]:
        sorted_scores = sorted(score, reverse=True)
        rank_map = {score: rank for rank, score in enumerate(sorted_scores, start=1)}
        ranks = []
        for s in score:
            if rank_map[s] == 1:
                ranks.append("Gold Medal")
            elif rank_map[s] == 2:
                ranks.append("Silver Medal")
            elif rank_map[s] == 3:
                ranks.append("Bronze Medal")
            else:
                ranks.append(str(rank_map[s]))
        return ranks

class Solution:
    def longestPalindrome(self, word1: str, word2: str) -> int:
        combined = word1 + word2
        n = len(combined)
        dp = [[0] * n for _ in range(n)]
        max_len = 0

        for length in range(1, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if length == 1:
                    dp[i][j] = 1
                elif length == 2:
                    dp[i][j] = 2 if combined[i] == combined[j] else 0
                else:
                    dp[i][j] = dp[i + 1][j - 1] + 2 if combined[i] == combined[j] else max(dp[i + 1][j], dp[i][j - 1])

                if i < len(word1) and j >= len(word1) and dp[i][j] > max_len:
                    max_len = dp[i][j]

        return max_len

class Solution:
    def checkArithmeticSubarrays(self, nums: List[int], l: List[int], r: List[int]) -> List[bool]:
        ans = []
        for i in range(len(l)):
            subarray = nums[l[i]:r[i]+1]
            if len(subarray) < 2:
                ans.append(False)
                continue
            diff = subarray[1] - subarray[0]
            for j in range(1, len(subarray)):
                if subarray[j] - subarray[j-1] != diff:
                    ans.append(False)
                    break
            else:
                ans.append(True)
        return ans

from typing import List

class Solution:
    def minOperations(self, logs: List[str]) -> int:
        depth = 0
        for log in logs:
            if log == "../":
                depth = max(0, depth - 1)
            elif log != "./":
                depth += 1
        return depth
